def _resolve_time_template(path: str) -> str:
    """
    Replace time-based placeholders in the path with actual values.
    """
    # Placeholder pattern: {year}, {month}, {day}, {hour}, {minute}, {second}
    pattern = re.compile(r"\{year\}|{month}|{day}|{hour}|{minute}|{second}\}")
    matches = pattern.finditer(path)

    for match in matches:
        placeholder = match.group()
        now = datetime.datetime.now()

        if placeholder == "{year}":
            path = path.replace(placeholder, str(now.year))
        elif placeholder == "{month}":
            path = path.replace(placeholder, str(now.month).zfill(2))
